{
  "tools": [
    {
      "name": "close_scene",
      "title": "Close Scene",
      "toolset": "scenefile",
      "description": "Close a scene tab. Refuses to throw away unsaved work unless you say so.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "scene": {
            "type": "string",
            "description": "Scene name or resource path. Empty for the active one."
          },
          "discardChanges": {
            "type": "boolean",
            "description": "Close even if the scene has unsaved changes.",
            "default": false
          }
        },
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Active": {
            "type": "string"
          },
          "ActivePath": {
            "type": "string"
          },
          "Open": {
            "type": "array",
            "items": {
              "type": "string"
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "editor_status",
      "title": "Get Editor Status",
      "toolset": "editor",
      "description": "Get the current state of the editor - engine version, which project is open, the active scene and whether it has unsaved changes, whether play mode is running or paused, how many tools are registered, the directory paths that matter (logs, project code and assets), and the state of the code compiler. Check IsCompiling/LastCompileSucceeded here after editing code instead of relying on read_console - a successful compile can scroll out of view or be mistaken for the last failure you saw.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "EngineVersion": {
            "type": "string"
          },
          "Project": {
            "type": "string"
          },
          "ProjectTitle": {
            "type": "string"
          },
          "ActiveScene": {
            "type": "string"
          },
          "ActiveScenePath": {
            "type": "string"
          },
          "SceneHasUnsavedChanges": {
            "type": "boolean"
          },
          "IsPlaying": {
            "type": "boolean"
          },
          "IsPaused": {
            "type": "boolean"
          },
          "ToolCount": {
            "type": "integer"
          },
          "IsCompiling": {
            "type": "boolean"
          },
          "LastCompileSucceeded": {
            "type": "boolean"
          },
          "LastCompileErrors": {
            "type": "integer"
          },
          "Paths": {
            "type": "object",
            "properties": {
              "Engine": {
                "type": "string"
              },
              "Logs": {
                "type": "string"
              },
              "ProjectRoot": {
                "type": "string"
              },
              "ProjectSettings": {
                "type": "string"
              }
            },
            "required": []
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_build_map",
      "title": "Build Map",
      "toolset": "hammer",
      "description": "Compile the open map, like pressing Build in Hammer's Build Map dialog (which opens to show progress). Saves the map first, since the compile reads what's on disk. Runs in the background - poll hammer_build_status until Building is false, then hammer_compiled_map_stats breaks down what was built. Doesn't launch the map unless loadInEngine is set.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "preset": {
            "type": "string",
            "enum": [
              "Full",
              "Fast",
              "Final",
              "EntitiesOnly",
              "Custom"
            ],
            "description": "Full, Fast (no vis or lighting - quickest), Final (final quality lighting), EntitiesOnly, or Custom for the dialog's current settings.",
            "default": "Fast"
          },
          "loadInEngine": {
            "type": "boolean",
            "description": "Load the map in engine when it's built, if the dialog is set to.",
            "default": false
          }
        },
        "required": []
      }
    },
    {
      "name": "hammer_compiled_map_stats",
      "title": "Compiled Map Stats",
      "toolset": "hammer",
      "description": "What the compiled map (.vpk) is made of - total size, size by kind (world geometry, lightmaps, physics, vis, entities...), the largest files, and whether it's older than the map's last save. Build with hammer_build_map first.",
      "inputSchema": {
        "type": "object",
        "properties": {
          "largest": {
            "type": "integer",
            "description": "How many of the largest files to list.",
            "minimum": 1,
            "maximum": 500,
            "default": 20
          }
        },
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      }
    },
    {
      "name": "hammer_save",
      "title": "Save",
      "toolset": "hammer",
      "description": "Save the open map to its file. A map that has never been saved has no file yet - the user needs to save it in Hammer first.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      }
    },
    {
      "name": "hammer_status",
      "title": "Status",
      "toolset": "hammer",
      "description": "Whether Hammer is open and what map it's editing - the map's asset path, unsaved changes, how many nodes of each kind it has, the selection mode and count, and the material active in Hammer's material browser. Start here before any other hammer_ tool. If Hammer isn't open, hammer_open_map opens a map in it.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Open": {
            "type": "boolean"
          },
          "MapOpen": {
            "type": "boolean"
          },
          "Map": {
            "type": "string"
          },
          "File": {
            "type": "string"
          },
          "HasUnsavedChanges": {
            "type": "boolean"
          },
          "NodeCounts": {
            "type": "object",
            "additionalProperties": {
              "type": "integer"
            }
          },
          "SelectionMode": {
            "type": "string"
          },
          "SelectedCount": {
            "type": "integer"
          },
          "CurrentMaterial": {
            "type": "string"
          },
          "ViewCount": {
            "type": "integer"
          }
        },
        "required": []
      }
    },
    {
      "name": "list_scenes",
      "title": "List Scenes",
      "toolset": "scene",
      "description": "List the scenes open in the editor - name, resource path, type (scene, prefab or the running game session), whether it's the active tab, unsaved changes, and root object count.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "annotations": {
        "readOnlyHint": true
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Scenes": {
            "type": "array",
            "items": {
              "type": "object",
              "properties": {
                "Name": {
                  "type": "string"
                },
                "ResourcePath": {
                  "type": "string"
                },
                "Type": {
                  "type": "string",
                  "description": "Scene, Prefab, or Game for the running session."
                },
                "IsActive": {
                  "type": "boolean"
                },
                "HasUnsavedChanges": {
                  "type": "boolean"
                },
                "RootObjectCount": {
                  "type": "integer"
                }
              },
              "required": []
            }
          }
        },
        "required": []
      }
    },
    {
      "name": "save_scene",
      "title": "Save Scene",
      "toolset": "scene",
      "description": "Save the active scene to its file.",
      "inputSchema": {
        "type": "object",
        "properties": {},
        "required": []
      },
      "outputSchema": {
        "type": "object",
        "properties": {
          "Saved": {
            "type": "string"
          },
          "HasUnsavedChanges": {
            "type": "boolean"
          }
        },
        "required": []
      }
    }
  ],
  "total": 128
}
